import{z as p,x as n,o as e,c as l,q as o,j as s,D as a,d as A,s as t,S as i,b as B}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"内核调试的方法","description":"","frontmatter":{"title":"内核调试的方法","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/osk-kernel-debugging.md","filePath":"cs/osk-kernel-debugging.md","lastUpdated":1791413859000}'),d={name:"cs/osk-kernel-debugging.md"};function c(D,E,u,C,m,F){const r=n("Mermaid");return e(),l("div",null,[E[2]||(E[2]=o('<h1 id="内核调试的方法" tabindex="-1">内核调试的方法 <a class="header-anchor" href="#内核调试的方法" aria-label="Permalink to &quot;内核调试的方法&quot;">​</a></h1><div class="epigraph"><p>内核调试的纪律是：证据要在事故之前采集——崩掉的内核不能给自己下断点。</p><footer>—— 据 Arpaci-Dusseau, OSTEP；内核 ftrace、kdump、KASAN 文档口径整理</footer></div><p><a href="/cs/osk-interrupt-drivers">上一课</a>让你往内核里放进了会碰硬件的代码；写错时的形态是 <a href="/cs/oops-panic">oops 与 panic</a> 两种死法。本课补实践面：一条栈回溯怎么变成源码行号，在线工具与转储镜像各在哪一步用，为什么开发内核要开着检测器编译。<a href="/cs/ftrace-tracepoints">ftrace 与 tracepoints</a> 已给工具本体，本课给的是组合使用的次序与各自的边界。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核出错与用户态不同：没有进程可以暂停，现场一旦被覆盖就没了；oops 文本里的寄存器与地址对未入门者是天书；很多 bug 只在特定时序下出现，等加打印再编译装载，问题已经不复现。实现面要回答：哪些证据必须运行时采集、哪些可以事后从镜像里挖、哪些只能靠构建期插桩拦下。不这么做会错在哪：对着发行版内核的十六进制回溯查一下午——没有符号表与调试信息，回溯只是一列地址，什么也说不出来；更糟的是用带排查代码的构建去测时序，插桩本身改变了时序，bug 消失了。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分三路。事后路：oops 文本里的出错地址与调用链，用同一次构建的、带调试信息的内核镜像经符号表还原成函数与行号；panic 则靠 kdump——启动时预留一小块内存放第二颗内核，崩溃时它接管并转储内存镜像，事后用 crash 一类工具查当时的进程、栈与对象。在线路：ftrace 的函数跟踪回答「路径走到了哪」，tracepoints 以稳定字段回答「经过了哪个点」，kprobe 在几乎任意指令地址挂回调回答「此刻这里的值是什么」，三者之上可跑脚本做聚合。重现路：开发构建打开 KASAN（越界与释放后使用）、lockdep（锁序反例）、KCSAN（数据竞争），它们把一类 bug 从「偶发崩溃、无法下手」变成「当场报告、带完整现场」。</p><p><span class="marginnote">术语翻译：oops 是内核「摔了一跤但还能爬起来」——杀死闯祸的任务、打印现场后系统继续跑；panic 是「伤及要害直接躺平」——整个内核停摆，只剩打印。oops 的文本是第一现场，panic 之后的事就交给 kdump 接手。</span></p>',8)),(e(),s(i,null,{default:a(()=>[t(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ERR%5B%22%E9%94%99%E8%AF%AF%E5%8F%91%E7%94%9F%22%5D%20--%3E%20JUDGE%7B%22oops%20%E5%8F%AF%E6%B4%BB%E8%BF%98%E6%98%AF%20panic%3F%22%7D%0A%20%20JUDGE%20--%3E%7Coops%20%E5%8F%AF%E6%B4%BB%7C%20LIVE%5B%22%E5%9C%A8%E7%BA%BF%E8%B7%AF%EF%BC%9Aftrace%20%E4%B8%8E%20kprobe%20%E5%A4%8D%E7%8E%B0%22%5D%0A%20%20JUDGE%20--%3E%7Cpanic%7C%20KD%5B%22%E4%BA%8B%E5%90%8E%E8%B7%AF%EF%BC%9Akdump%20%E8%BD%AC%E5%82%A8%E9%95%9C%E5%83%8F%22%5D%0A%20%20LIVE%20--%3E%20SYM%5B%22%E7%AC%A6%E5%8F%B7%E8%BF%98%E5%8E%9F%E4%B8%BA%E5%87%BD%E6%95%B0%E4%B8%8E%E8%A1%8C%E5%8F%B7%22%5D%0A%20%20KD%20--%3E%20CRASH%5B%22crash%20%E5%B7%A5%E5%85%B7%E6%9F%A5%E6%A0%88%E4%B8%8E%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20SYM%20--%3E%20FIX%5B%22%E5%AE%9A%E4%BD%8D%E5%B9%B6%E4%BF%AE%E6%94%B9%22%5D%0A%20%20CRASH%20--%3E%20FIX%0A%20%20SAN%5B%22%E9%87%8D%E7%8E%B0%E8%B7%AF%EF%BC%9AKASAN%E3%80%81lockdep%E3%80%81KCSAN%22%5D%20-.-%3E%7C%E6%9E%84%E5%BB%BA%E6%9C%9F%E6%8B%A6%E6%88%AA%7C%20FIX%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[A("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"各工具能工作，靠的都是提前埋好的结构。符号表留在内核里，回溯才有函数名；影子内存按字节记录可访问性，每次访存前多查一次影子，越界当场暴露；kdump 的第二颗内核不依赖崩溃者——崩掉的内核连自己的内存都不可信，这是它必须预留在启动时的全部理由。tracepoint 与 kprobe 的分工也有结构性原因：前者是开发者显式埋的点，字段有契约、跨版本稳定；后者挂在任意地址，内核一改就漂——所以长期监控用前者，现场挖掘才用后者。为什么插桩改变时序是原则性困难：检测器的每次检查都插入额外执行，海森 bug 的「观测改变被观测」在内核里是物理事实，只能靠「尽量轻的桩」与「关掉桩再验证」来缓解。",-1)),(e(),s(i,null,{default:a(()=>[t(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20LD%5B%22%E4%BB%A3%E7%A0%81%E8%A6%81%E8%AF%BB%E5%86%99%E5%9C%B0%E5%9D%80%20A%22%5D%20--%3E%20SHADOW%5B%22%E6%9F%A5%E5%BD%B1%E5%AD%90%E5%86%85%E5%AD%98%E9%87%8C%20A%20%E5%AF%B9%E5%BA%94%E7%9A%84%E5%AD%97%E8%8A%82%22%5D%0A%20%20SHADOW%20--%3E%20OKQ%7B%22%E5%BD%B1%E5%AD%90%E5%85%81%E8%AE%B8%E8%BF%99%E6%AC%A1%E8%AE%BF%E9%97%AE%E5%90%97%3F%22%7D%0A%20%20OKQ%20--%3E%7C%22%E5%85%81%E8%AE%B8%22%7C%20PASS%5B%22%E6%94%BE%E8%A1%8C%2C%20%E6%AD%A3%E5%B8%B8%E8%AE%BF%E5%AD%98%22%5D%0A%20%20OKQ%20--%3E%7C%22%E8%B6%8A%E7%95%8C%E6%88%96%E5%B7%B2%E9%87%8A%E6%94%BE%22%7C%20RPT%5B%22%E5%BD%93%E5%9C%BA%E6%8A%A5%E5%91%8A%3A%20%E8%AE%BF%E9%97%AE%E6%A0%88%E5%8A%A0%E5%88%86%E9%85%8D%E6%A0%88%22%5D%0A%20%20PASS%20--%3E%20CONT%5B%22%E7%A8%8B%E5%BA%8F%E7%BB%A7%E7%BB%AD%E8%BF%90%E8%A1%8C%22%5D%0A%20%20RPT%20--%3E%20STOP%5B%22%E6%B5%8B%E8%AF%95%E7%AB%8B%E5%88%BB%E5%A4%B1%E8%B4%A5%2C%20%E7%8E%B0%E5%9C%BA%E5%AE%8C%E6%95%B4%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=o('<p><span class="marginnote">直觉类比：kdump 像备用摄像师——主镜（崩溃的内核）摔碎时不能指望它自己拍自己，所以开演前就在后台机位安排好一台独立相机（预留内存里的第二颗内核）；事故瞬间接管机位，把现场（内存镜像）原样拍下来带走。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>性能问题与功能 bug 工具集不同：火焰图与硬件计数是观测课的对象，本课只管「错在哪」。安全漏洞的利用分析、用户态调试器都有各自去处。版本漂移照旧：工具名与配置项会变，课序钉的是「事后、在线、重现」三路分工与「证据先于事故」这条纪律——拿这条纪律去对任何内核的调试设施，结构都对得上。</p><p><span class="marginnote">常见误区：在开了 KASAN 的构建里跑不出来，就断定「没有这个 bug」。插桩本身改变时序，偶发时序 bug 可能恰好被压住；正确次序是先用检测器抓确定性问题，再关掉桩、贴近生产配置去验证时序类问题。</span></p><p><span class="marginnote">KASAN 的影子内存约占地址空间的八分之一，运行时代价常见两到三倍——所以它只进开发与测试构建。反过来，未开检测的生产构建里，越界写可能安静地破坏几页之外的对象，症状出现在完全无关的路径上，定位成本反而更高。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内核调试三路：事后还原（符号与转储镜像）、在线追踪（ftrace 与 kprobe）、构建期检测（KASAN、lockdep、KCSAN）。</li><li>同版本带调试信息的内核镜像是第一生产力，保存它运维纪律。</li><li>kdump 的第二颗内核不信任崩溃者；影子内存的代价决定了检测器只进测试构建。</li><li>tracepoint 有字段契约、kprobe 没有稳定接口：长期监控用前者，现场挖掘用后者。</li><li>出处：Arpaci-Dusseau, <em>OSTEP</em>；内核 ftrace、kdump、KASAN 文档口径整理。</li></ul>',7))])}const f=p(d,[["render",c]]);export{S as __pageData,f as default};
